-- RID=24 | MENU=3 | ITEM=1 | RQUERY=1 | NAME=Daftar Permintaan Barang (MR) | FILE=listmaterialrequisition
SELECT mr.mrnotransaksi , mr.mrtgl , mr.mrtgldipakai, kd.knama AS mrdimintaoleh, km.knama AS mrmintake , wa.wnama AS mrgudangasal , wt.wnama AS mrgudangtujuan, mr.mruraian , st.nama AS mrstatus , b.bkode , mrd.namabarang , mrd.jml, mrd.satuan , mrd.catatan FROM m3_mr mr JOIN m1_contact kd ON mr.mrdimintaoleh = kd.kid JOIN m1_contact km ON mr.mrmintake = km.kid JOIN m1_warehouse wa ON mr.mrgudangasal = wa.wkode JOIN m1_warehouse wt ON mr.mrgudangtujuan = wt.wkode JOIN m0_status st on mr.mrstatus = st.kode join m3_mr_detail mrd ON mr.mrid = mrd.idmr JOIN m1_item b ON mrd.idbarang = b.bid ORDER BY mr.mrtgl , mr.mrid , mr.mrnotransaksi, mrd.urutan;

-- RID=25 | MENU=3 | ITEM=2 | RQUERY=1 | NAME=Permintaan Barang (MR) | FILE=materialrequisitiondetail_new
