-- RID=330 | MENU=3 | ITEM=4 | RQUERY=1 | NAME=Daftar Permintaan Barang (MR) Perproduk | FILE=listmaterialrequisition_Product
SELECT b.bid , b.bkode , mrd.namabarang , mr.mrnotransaksi , mr.mrtgl , mr.mrtgldipakai, kd.knama AS mrdimintaoleh , km.knama AS mrmintake , wa.wnama AS mrgudangasal , wt.wnama AS mrgudangtujuan , st.nama AS mrstatus , SUM(mrd.jml) as jml , mrd.satuan FROM m3_mr mr JOIN m1_contact kd ON mr.mrdimintaoleh = kd.kid JOIN m1_contact km ON mr.mrmintake = km.kid JOIN m1_warehouse wa ON mr.mrgudangasal = wa.wkode JOIN m1_warehouse wt ON mr.mrgudangtujuan = wt.wkode JOIN m0_status st on mr.mrstatus = st.kode join m3_mr_detail mrd ON mr.mrid = mrd.idmr JOIN m1_item b ON mrd.idbarang = b.bid GROUP BY mrd.idbarang , b.bid , b.bkode, mrd.namabarang , mrd.satuan , mrd.idmr ORDER BY mrd.idbarang , b.bid , b.bkode, mrd.namabarang;

-- RID=335 | MENU=3 | ITEM=5 | RQUERY=1 | NAME=Daftar Permintaan Barang (MR) Outstanding | FILE=listmaterialrequisitionoutstanding
SELECT mr.mrnotransaksi , mr.mrtgl , kd.knama AS mrdimintaoleh, wa.wnama AS mrgudangasal , wt.wnama AS mrgudangtujuan, mr.mruraian , b.bkode , mrd.namabarang , mrd.jml, mrd.satuan , (mrd.jmlrealisasi / mrd.nilaisatuan) AS jmlrealisasi , (mrd.jml - (mrd.jmlrealisasi / mrd.nilaisatuan)) as jmlsisa , mrd.catatan FROM m3_mr mr JOIN m1_contact kd ON mr.mrdimintaoleh = kd.kid JOIN m1_warehouse wa ON mr.mrgudangasal = wa.wkode JOIN m1_warehouse wt ON mr.mrgudangtujuan = wt.wkode join m3_mr_detail mrd ON mr.mrid = mrd.idmr JOIN m1_item b ON mrd.idbarang = b.bid ORDER BY mr.mrtgl , mr.mrid , mr.mrnotransaksi, mrd.urutan;

-- RID=337 | MENU=3 | ITEM=6 | RQUERY=1 | NAME=Daftar Permintaan Barang (MR) Outstanding Sisa | FILE=listmaterialrequisitionoutstandingsisa
SELECT mr.mrnotransaksi, mr.mrtgl, mr.mruraian, ga.wnama AS gudangasal, gt.wnama AS gudangtujuan, b.bkode, (CASE mr.mrstatus WHEN 0 THEN 'Draft' WHEN 1 THEN 'Minta Approve' WHEN 2 THEN 'Approved' WHEN 3 THEN 'Inprogress' WHEN 4 THEN 'Complete' WHEN 5 THEN 'Revisi' WHEN 6 THEN 'Reject' WHEN 7 THEN 'Close' WHEN 8 THEN 'Approve1' WHEN 9 THEN 'Approve2' WHEN 10 THEN 'Approve3' WHEN 11 THEN 'Approve4' WHEN 12 THEN 'Hapus' END) AS status, ((mrd.jml) - IFNULL(mrd.jmlrs,0)) AS jmlrs, ((mrd.jml) - IFNULL(mrd.jmlts,0)) AS jmlts, mrd.namabarang, mrd.tipebarang, mrd.jml, mrd.satuan, mrd.catatan FROM m3_mr mr JOIN m3_mr_detail mrd ON mr.mrid = mrd.idmr JOIN m1_item b ON mrd.idbarang = b.bid LEFT JOIN m1_warehouse ga ON mr.mrgudangasal = ga.wkode LEFT JOIN m1_warehouse gt ON mr.mrgudangtujuan = gt.wkode ORDER BY mr.mrnotransaksi, mrd.urutan;

-- RID=554 | MENU=3 | ITEM=7 | RQUERY=1 | NAME=Permintaan Barang (MR) | FILE=materialrequisitiondetail_ud
SELECT mr.mrnotransaksi , mr.mrtgl , mr.mrtgldipakai, kd.knama AS mrdimintaoleh, km.knama AS mrmintake , wa.wnama AS mrgudangasal , wt.wnama AS mrgudangtujuan, mr.mruraian , st.nama AS mrstatus , b.bkode , mrd.namabarang , mrd.jml, mrd.satuan , mrd.catatan FROM m3_mr mr JOIN m1_contact kd ON mr.mrdimintaoleh = kd.kid JOIN m1_contact km ON mr.mrmintake = km.kid JOIN m1_warehouse wa ON mr.mrgudangasal = wa.wkode JOIN m1_warehouse wt ON mr.mrgudangtujuan = wt.wkode JOIN m0_status st on mr.mrstatus = st.kode join m3_mr_detail mrd ON mr.mrid = mrd.idmr JOIN m1_item b ON mrd.idbarang = b.bid ORDER BY mr.mrtgl , mr.mrid , mr.mrnotransaksi, mrd.urutan;

-- RID=1096 | MENU=3 | ITEM=8 | RQUERY=1 | NAME=Daftar Permintaan Barang (MR) Stok Global | FILE=MRStokGlobal
SELECT COUNT(*) , wa.wnama AS mrgudangasal , mr.mrnotransaksi , mrd.idbarang , b.bkode AS kodebarang, mrd.namabarang , SUM(mrd.jml) AS jml, mrd.satuan , SUM(mrd.jmlrealisasi / mrd.nilaisatuan) AS jmlrealisasi , SUM(mrd.jml - (mrd.jmlrealisasi / mrd.nilaisatuan)) as jmlsisa , (stok.stok - SUM(mrd.jml - (mrd.jmlrealisasi / mrd.nilaisatuan))) AS sisa , stok.stok FROM m3_mr mr JOIN m1_contact kd ON mr.mrdimintaoleh = kd.kid JOIN m1_warehouse wa ON mr.mrgudangasal = wa.wkode JOIN m1_warehouse wt ON mr.mrgudangtujuan = wt.wkode join m3_mr_detail mrd ON mr.mrid = mrd.idmr JOIN m1_item b ON mrd.idbarang = b.bid JOIN m1_item_stock_warehouse stok ON mrd.idbarang = stok.idbarang AND mr.mrgudangasal = stok.kgudang GROUP BY mr.mrgudangasal , mrd.idbarang ORDER BY mr.mrgudangasal , mrd.idbarang, mrd.idbarang;

