-- RID=26 | MENU=4 | ITEM=1 | RQUERY=1 | NAME=Daftar Mutasi Barang (TS) | FILE=listtransferstock
SELECT ts.tsid , ts.tsnotransaksi , ts.tstgl , wa.wnama AS tsgudangasal , wt.wnama AS tsgudangtransit, wtu.wnama AS tsgudangtujuan, ts.tsuraian , st.nama AS tsstatus , b.bkode , tsd.namabarang , tsd.jml , tsd.satuan , tsd.catatan , mr.mrnotransaksi FROM m3_ts ts JOIN m1_warehouse wa ON ts.tsgudangasal = wa.wkode JOIN m1_warehouse wt ON ts.tsgudangtransit = wt.wkode JOIN m1_warehouse wtu ON ts.tsgudangtujuan = wtu.wkode JOIN m0_status st ON ts.tsstatus = st.kode JOIN m3_ts_detail tsd ON ts.tsid = tsd.idts JOIN m1_item b ON tsd.idbarang = b.bid LEft JOIN m3_mr_detail mrd ON mrd.idmrdetail = tsd.idmrdetail LEFt JOIN m3_mr mr ON mrd.idmr = mr.mrid ORDER BY ts.tstgl , ts.tsid , ts.tsnotransaksi , tsd.urutan;

