SELECT sa.said , COUNT(*), sa.sagudang , w.wnama AS gudang, sa.sanotransaksi , sa.satgl , sa.sauraian , sa.sacatatan , tsa.tsanama AS sajenis , st.nama AS sastatus, b.bkode , sad.namabarang , sad.satuan , SUM(sad.jmlmasuk) as jmlmasuk , SUM(sad.jmlkeluar) as jmlkeluar, sad.hpplama, sad.hpp, sad.idbarang , sad.catatan FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode JOIN m0_status st ON sa.sastatus = st.kode GROUP BY sa.satgl , sa.said , sad.idbarang , sad.namabarang , sad.satuan , sad.hpp, sad.hpplama ORDER BY sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.idbarang, sad.urutan;

