-- RID=1023 | MENU=7 | ITEM=7 | RQUERY=1 | NAME=Stok Opname (SP) Per Produk | FILE=liststockopname_product
SELECT b.bid, b.bkode, spd.namabarang, il.ilnama AS lokasi , sp.spnotransaksi , sp.sptgl , w.wnama AS spgudang, spd.satuan , SUM(spd.jmlsistem) AS jmlsistem, SUM(spd.jmlfisik) AS jmlfisik , SUM(spd.jmlbagus) AS jmlbagus , SUM(spd.jmlrusak) AS jmlrusak, SUM(spd.jmlsistem - spd.jmlfisik ) AS jmlselisih FROM m3_sp sp JOIN m1_warehouse w ON sp.spgudang = w.wkode JOIN m0_status st ON sp.spstatus = st.kode JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang GROUP BY spd.idbarang , b.bid, b.bkode, spd.namabarang, spd.satuan, spd.idsp ORDER BY spd.idbarang , b.bid , spd.namabarang;

-- RID=46 | MENU=7 | ITEM=8 | RQUERY=1 | NAME=Stok Opaname (SP) Dengan Saldo | FILE=liststockopnamewithbalance
SELECT spd.urutan, sp.spnotransaksi, sp.sptgl, spd.jmlfisik, spd.jmlbagus, spd.jmlsistem, spd.jmlrusak, b.btipe, b.bnama, b.bkode, b.bsatuan, blg.blgnamalokasi FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location_warehouse blg ON spd.idbarang = blg.blgidbarang AND sp.spgudang = blg.blggudang;

-- RID=47 | MENU=7 | ITEM=9 | RQUERY=1 | NAME=Stok Opname (SP) Perproduk | FILE=liststockopnameperproduct
SELECT sp.spnotransaksi, sp.sptgl, sp.spuraian, SUM(spd.jmlsistem) AS jumlahbuku, SUM(spd.jmlfisik) AS jumlahfisik, b.bkode, b.btipe, b.bnama, b.bsatuan, g.wnama, blg.blgnamalokasi, SUM((spd.jmlsistem - spd.jmlfisik)) AS selisih FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location_warehouse blg ON (spd.idbarang = blg.blgidbarang AND sp.spgudang = blg.blggudang) LEFT JOIN m1_warehouse g ON sp.spgudang = g.wkode GROUP BY b.bkode, b.btipe, b.bnama, b.bsatuan, sp.spnotransaksi ORDER BY b.bkode, spd.urutan, sp.spnotransaksi;

-- RID=49 | MENU=7 | ITEM=10 | RQUERY=1 | NAME=Stok Opname (SP) Outstanding Sisa | FILE=liststockopnameoutstandingsisa
SELECT sp.spnotransaksi, sp.sptgl, sp.spcatatan, spd.jmlrusak, spd.jmlsa, (CASE sp.spstatus WHEN 0 THEN 'Draft' WHEN 1 THEN 'Minta Approve' WHEN 2 THEN 'Approved' WHEN 3 THEN 'Inprogress' WHEN 4 THEN 'Complete' WHEN 5 THEN 'Revisi' WHEN 6 THEN 'Reject' WHEN 7 THEN 'Close' WHEN 8 THEN 'Approve1' WHEN 9 THEN 'Approve2' WHEN 10 THEN 'Approve3' WHEN 11 THEN 'Approve4' WHEN 12 THEN 'Hapus' END) AS spstatus, b.bkode AS kodebarang, b.bnama AS namabarang, b.btipe, b.bsatuan, g.wnama, sp.spuraian, blg.blgnamalokasi FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid JOIN m1_warehouse g ON sp.spgudang = g.wkode LEFT JOIN m1_item_location_warehouse blg ON (spd.idbarang = blg.blgidbarang AND sp.spgudang = blg.blggudang) WHERE (sp.spstatussa <> 'S' AND spd.statussa <> 'S') ORDER BY sp.spnotransaksi, spd.urutan;

-- RID=565 | MENU=7 | ITEM=11 | RQUERY=1 | NAME=Stok Opname (SP) | FILE=stockopnamedetail_ud
SELECT sp.spnotransaksi , sp.sptgl , w.wnama AS spgudang , sp.spuraian , st.nama AS spstatus , il.ilnama as lokasibarang , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, spd.jmlfisik , spd.jmlbagus , spd.jmlrusak, (spd.jmlsistem - spd.jmlfisik ) AS jmlselisih FROM m3_sp sp JOIN m1_warehouse w ON sp.spgudang = w.wkode JOIN m0_status st ON sp.spstatus = st.kode JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang ORDER BY sp.sptgl , sp.spid , sp.spnotransaksi , spd.urutan;

-- RID=1343 | MENU=7 | ITEM=12 | RQUERY=1 | NAME=Blanko Stok Opname Dengan Saldo | FILE=BlankoStokOpnameDenganSaldo
SELECT sp.sptgl , sp.spnotransaksi , il.ilnama , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, (spd.jmlbagus + spd.jmlrusak)AS jmlfisik, spd.jmlbagus , spd.jmlrusak FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang ORDER BY sp.sptgl , sp.spnotransaksi , il.ilkode;

-- RID=1344 | MENU=7 | ITEM=13 | RQUERY=1 | NAME=Blanko Stok Opname Tanpa Saldo | FILE=BlankoStokOpnameTanpaSaldo
SELECT sp.sptgl , sp.spnotransaksi , il.ilnama , b.bkode , spd.namabarang , spd.satuan, spd.jmlsistem FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang ORDER BY sp.sptgl , sp.spnotransaksi , spd.idbarang , il.ilkode;

-- RID=1345 | MENU=7 | ITEM=14 | RQUERY=1 | NAME=Hasil Stok Opname | FILE=HasilStokOpname
SELECT sp.sptgl , sp.spnotransaksi , w.wnama AS gudang , il.ilnama , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, spd.jmlfisik , spd.jmlbagus , spd.jmlrusak , spd.selisih FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid JOIN m1_warehouse w ON sp.spgudang = w.wkode LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang ORDER BY sp.sptgl , sp.spnotransaksi , il.ilkode;

-- RID=1346 | MENU=7 | ITEM=15 | RQUERY=1 | NAME=Blanko Stok Opname Selisih Tanpa Saldo | FILE=BlankoStokOpanameSelisihTanpaSaldo
SELECT w.wnama AS gudang , il.ilnama , b.bkode , spd.namabarang , spd.satuan , SUM(spd.jmlsistem) AS jmlsistem, SUM(spd.jmlfisik) AS jmlfisik , SUM(spd.jmlbagus) AS jmlbagus , SUM(spd.jmlrusak) AS jmlrusak , SUM(spd.selisih) AS selisih FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid JOIN m1_warehouse w ON sp.spgudang = w.wkode LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang WHERE spd.selisih <> 0 GROUP BY sp.spgudang , b.bkode , il.ilkode ORDER BY sp.spgudang , b.bkode , il.ilkode;

-- RID=1347 | MENU=7 | ITEM=16 | RQUERY=1 | NAME=Blanko Stok Opname Selisih Dengan Saldo | FILE=BlankoStokOpanameSelisihDenganSaldo
SELECT w.wnama AS gudang , il.ilnama , b.bkode , spd.namabarang , spd.satuan , SUM(spd.jmlsistem) AS jmlsistem, SUM(spd.jmlfisik) AS jmlfisik , SUM(spd.jmlbagus) AS jmlbagus , SUM(spd.jmlrusak) AS jmlrusak , SUM(spd.selisih) AS selisih FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid JOIN m1_warehouse w ON sp.spgudang = w.wkode LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang WHERE spd.selisih <> 0 GROUP BY sp.spgudang , il.ilkode, b.bkode , spd.namabarang ORDER BY sp.spgudang , il.ilkode, b.bkode , spd.namabarang;

-- RID=1644 | MENU=7 | ITEM=17 | RQUERY=1 | NAME=Daftar Stok Opname (SP) | FILE=liststockopname2
SELECT sp.spnotransaksi , sp.sptgl , w.wnama AS spgudang , sp.spuraian , st.nama AS spstatus , il.ilnama as lokasibarang , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, spd.jmlfisik , spd.jmlbagus , spd.jmlrusak, (spd.jmlsistem - spd.jmlfisik ) AS jmlselisih FROM m3_sp sp JOIN m1_warehouse w ON sp.spgudang = w.wkode JOIN m0_status st ON sp.spstatus = st.kode JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang;

-- RID=1653 | MENU=7 | ITEM=18 | RQUERY=1 | NAME=Laporan Hasil Stock Opname Pertahap  | FILE=liststockopname_step
SELECT sp.spid , sp.spnotransaksi , sp.sptgl , w.wnama AS spgudang , sp.spuraian , st.nama AS spstatus , spd.idsp , spd.idspdetail , spd.idbarang , il.ilnama as lokasibarang , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, spd.jmlfisik , spd.jmlbagus , spd.jmlrusak, (spd.jmlsistem - spd.jmlfisik ) AS jmlselisih FROM m3_sp sp JOIN m1_warehouse w ON sp.spgudang = w.wkode JOIN m0_status st ON sp.spstatus = st.kode JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang ORDER BY sp.sptgl , sp.spid , sp.spnotransaksi , spd.idbarang , spd.urutan;

-- RID=1654 | MENU=7 | ITEM=19 | RQUERY=1 | NAME=Stok Opname (SP) Blanko Selisih | FILE=stockopnamedetail_selisih_blanko
SELECT sp.spnotransaksi , sp.sptgl , w.wnama AS spgudang , sp.spuraian , st.nama AS spstatus , il.ilnama as lokasibarang , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, (spd.jmlsistem - spd.jmlfisik ) AS jmlselisih FROM m3_sp sp JOIN m1_warehouse w ON sp.spgudang = w.wkode JOIN m0_status st ON sp.spstatus = st.kode JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang WHERE (spd.jmlsistem - spd.jmlfisik ) <> 0 ORDER BY sp.sptgl , sp.spid , sp.spnotransaksi , spd.urutan;

-- RID=1658 | MENU=7 | ITEM=20 | RQUERY=1 | NAME=Blanko Stok Opname Selisih Dengan Saldo Penjualan | FILE=BlankoStokOpanameSelisihDenganSaldo_jual
SELECT sp.spid, sp.spnotransaksi, sp.sptgl, w.wnama AS spgudang, st.nama AS spstatus , sp.spuraian , spd.idspdetail, spd.idbarang, il.ilnama as lokasibarang , b.bkode , spd.namabarang, spd.satuan , spd.jmlbarangsistem, spd.jmlbarangfisik, spd.jmlbarangbagus, spd.jmlbarangrusak, SUM((CASE LENGTH(IFNULL(si.siid,'')) WHEN 0 THEN 0 ELSE sid.jmlbarang END) ) as jmlbarangjual, spd.jmlbarangsistem - SUM((CASE LENGTH(IFNULL(si.siid,'')) WHEN 0 THEN 0 ELSE sid.jmlbarang END) ) - spd.jmlbarangfisik as selisihbarangfix FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp LEFT JOIN m5_si_detail sid ON spd.idbarang = sid.idbarang LEFT JOIN m5_si si ON sid.idsi = si.siid AND sp.sptgl = si.sitgl AND sp.spgudang = si.sigudang AND si.sistatus IN(2,3,4,7) JOIN m0_status st ON sp.spstatus = st.kode JOIN m1_warehouse w ON spgudang = w.wkode LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang JOIN m1_item b ON spd.idbarang = b.bid GROUP BY spd.idspdetail HAVING selisihbarangfix <> 0 ORDER BY sp.spgudang , il.ilkode, b.bkode , spd.namabarang;

-- RID=1659 | MENU=7 | ITEM=21 | RQUERY=1 | NAME=Stok Opname (SP) Blanko Selisih Penjualan | FILE=stockopnamedetail_jual
SELECT sp.spid, sp.spnotransaksi, sp.sptgl, w.wnama AS spgudang, st.nama AS spstatus , sp.spuraian , spd.idspdetail, spd.idbarang, il.ilnama as lokasibarang , b.bkode , spd.namabarang, spd.satuan , spd.jmlbarangsistem, spd.jmlbarangfisik, spd.jmlbarangbagus, spd.jmlbarangrusak, SUM((CASE LENGTH(IFNULL(si.siid,'')) WHEN 0 THEN 0 ELSE sid.jmlbarang END) ) as jmlbarangjual, spd.jmlbarangsistem - SUM((CASE LENGTH(IFNULL(si.siid,'')) WHEN 0 THEN 0 ELSE sid.jmlbarang END) ) - spd.jmlbarangfisik as selisihbarangfix FROM m3_sp sp JOIN m3_sp_detail spd ON sp.spid = spd.idsp LEFT JOIN m5_si_detail sid ON spd.idbarang = sid.idbarang LEFT JOIN m5_si si ON sid.idsi = si.siid AND sp.sptgl = si.sitgl AND sp.spgudang = si.sigudang AND si.sistatus IN(2,3,4,7) JOIN m0_status st ON sp.spstatus = st.kode JOIN m1_warehouse w ON spgudang = w.wkode LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang JOIN m1_item b ON spd.idbarang = b.bid GROUP BY spd.idspdetail HAVING selisihbarangfix <> 0 ORDER BY sp.spid, spd.idspdetail;

-- RID=1665 | MENU=7 | ITEM=22 | RQUERY=1 | NAME=Daftar Stok Opname (SP) Dengan Harga | FILE=liststockopnamedenganharga
SELECT sp.spnotransaksi , sp.sptgl , w.wnama AS spgudang , sp.spuraian , st.nama AS spstatus , il.ilnama as lokasibarang , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, spd.jmlfisik , spd.jmlbagus , spd.jmlrusak, (spd.jmlsistem - spd.jmlfisik ) AS jmlselisih, b.bhargajual1 AS hargajual FROM m3_sp sp JOIN m1_warehouse w ON sp.spgudang = w.wkode JOIN m0_status st ON sp.spstatus = st.kode JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang ORDER BY sp.sptgl , sp.spid , sp.spnotransaksi , spd.urutan;

