SELECT paid, pacabang, palokasi, pagudang, pakategori, pakategoriharga, pasumber, paautonotransaksi, panotransaksi, patgl, patglberlakusampai, pakodepa, pabagianpa, pabagianpakontak, pamatauang, pakurs, pauraian, pacatatan, panoref, patglnoref, pastatus, pastatussebelumnya, pajmlrevisi, pacetakanke, painputuser, painputtgl, pamodifikasiuser, pamodifikasitgl, paposting, papostingtgl, patutupperiode, paisclose, idpadetail, idpa, idbarang, satuan, nilaisatuan, kontak, matauang, kurs, hargajual1lama, hargajual2lama, hargajual3lama, hargajual4lama, hargajual5lama, hargajual1, hargajual2, hargajual3, hargajual4, hargajual5, diskonjual1lama, diskonjual2lama, diskonjual3lama, diskonjual4lama, diskonjual5lama, diskonjual1, diskonjual2, diskonjual3, diskonjual4, diskonjual5, cabang, lokasi, gudang, costcenter, divisi, subdivisi, proyek, catatan, urutan, statusberlaku, isclose, hargajual6lama, hargajual7lama, hargajual8lama, hargajual9lama, hargajual10lama, hargajual6, hargajual7, hargajual8, hargajual9, hargajual10, diskonjual6, diskonjual7, diskonjual8, diskonjual9, diskonjual10 FROM m3_pa pa JOIN m3_pa_detail pad ON pa.paid = pad.idpa ORDER BY m3_pa pa pa.patgl ASC, pa.paid ASC , pad.idpadetail ASC;

-- RID=50000604 | MENU=12 | ITEM=21 | RQUERY=1 | NAME=Laporan Retur Penjualan Per Customer | FILE=returpercustomer
SELECT kc.kkode AS kodecustomer , kc.knama AS sicustomer , sr.srnotransaksi , sr.srtgl , ks.kkode AS kodesalesman , kc.knama AS sibagianpenjualan , sr.srkurs , sr.srmatauang , SUM(srd.jml) AS jml , SUM(((srd.jml * srd.harga) - srd.jmldiskon) - srd.jmlpajak1) AS total , sr.srjmldiskon , (sr.srtotalpajak1detail + sr.srtotalpajak2detail) AS srtotalpajak1detail , sr.srbiayalain , sr.srtotaltransaksi FROM m5_sr sr JOIN m5_sr_detail srd ON sr.srid = srd.idsr JOIN m1_contact kc ON sr.srcustomer = kc.kid JOIN m1_contact ks ON sr.srbagianpenjualan = ks.kid WHERE (sr.srstatus = 2 OR sr.srstatus = 3 OR sr.srstatus = 4 OR sr.srstatus = 7 ) GROUP BY sr.srcustomer ASC , sr.srtgl ASC , sr.srid ASC ORDER BY sr.srcustomer ASC , sr.srtgl ASC , sr.srid ASC;

-- RID=50000605 | MENU=12 | ITEM=22 | RQUERY=1 | NAME=Laporan Retur Penjualan Per Kategori Barang | FILE=returperkategoribarang
SELECT CASE sr.srhargatermasukpajak WHEN 0 THEN (srd.jmlpajak1 * 0) WHEN 1 THEN (srd.jmlpajak1 * 1) END AS pengurangansubt , sr.srhargatermasukpajak AS sihargatermasukpajak, CASE sr.srhargatermasukpajak WHEN 0 THEN "Belum Termasuk Pajak" WHEN 1 THEN "Sudah Termasuk Pajak" END AS caption , CASE sr.srhargatermasukpajak WHEN 0 THEN (srd.jmlpajak1 * 1) WHEN 1 THEN (srd.jmlpajak1 * 0) END AS pajak , srd.idbarang AS grup , sr.srid AS siid , sr.srtgl AS sitgl , sr.srnotransaksi AS sinotransaksi , kc.knama AS sicustomer , ks.knama AS sibagianpenjualan , sr.srtermin AS sitermin , st.nama AS sistatus , sr.sruraian AS siuraian , sr.srmatauang AS simatauang , sr.srkurs AS sikurs , sr.srdiskonpersen AS sidiskonpersen , sr.srjmldiskon AS sijmldiskon, sr.srbiayalain AS sibiayalain , sr.srtotalpajak1detail AS sitotalpajak1detail, sr.srtotaltransaksi AS sitotaltransaksi , b.bkategori , ic.icnama AS kategori, b.bkode , srd.namabarang , srd.catatan , srd.jml , srd.satuan , srd.harga , srd.diskon , ((srd.jml * srd.harga) - srd.jmldiskon) - srd.jmlpajak1 AS total , srd.jmlpajak1 FROM m5_sr sr JOIN m1_contact kc ON sr.srcustomer = kc.kid JOIN m1_contact ks ON sr.srbagianpenjualan = ks.kid JOIN m0_status st on sr.srstatus = st.kode JOIN m5_sr_detail srd ON sr.srid = srd.idsr JOIN m1_item b on srd.idbarang = b.bid JOIN m1_item_category ic ON b.bkategori = ic.ickode WHERE (sr.srstatus = 2 OR sr.srstatus = 3 OR sr.srstatus = 4 OR sr.srstatus = 7 ) ORDER BY b.bkategori, srd.idbarang , b.bkode , srd.namabarang , sr.srtgl , sr.srid, sr.srnotransaksi , srd.urutan;

-- RID=50000606 | MENU=12 | ITEM=23 | RQUERY=1 | NAME=Laporan Retur Penjualan Per Customer Per Produk | FILE=retur_Per_Customer_Per_Produk
SELECT kc.kkode , kc.knama , b.bkode , b.bnama , SUM(srd.jml) AS jml , srd.satuan , srd.harga , (SUM(srd.jml * srd.harga) - SUM(srd.jmldiskon) - SUM(srd.pajak1)) AS total , SUM(srd.pajak1) AS pajak1 , CASE sr.srhargatermasukpajak WHEN 0 THEN (srd.jmlpajak1 * 0) WHEN 1 THEN (srd.jmlpajak1 * 1) END AS pengurangansubt FROM m5_sr sr JOIN m1_contact kc ON sr.srcustomer = kc.kid JOIN m5_sr_detail srd ON sr.srid = srd.idsr JOIN m1_item b ON srd.idbarang = b.bid WHERE (sr.srstatus = 2 OR sr.srstatus = 3 OR sr.srstatus = 4 OR sr.srstatus = 7 ) GROUP BY sr.srcustomer ASC , srd.idbarang ASC ORDER BY sr.srcustomer ASC , srd.idbarang ASC;

-- RID=50000607 | MENU=12 | ITEM=24 | RQUERY=1 | NAME=Laporan Retur Penjualan Per Customer Detail | FILE=returpercustomer_detail
SELECT expe.enama , sr.srekspedisi AS siekspedisi , sr.srbagianpenjualan AS sihargatermasukpajak , CASE sr.srhargatermasukpajak WHEN 0 THEN "Belum Termasuk Pajak" WHEN 1 THEN "Sudah Termasuk Pajak" END AS caption , sr.srid AS siid , sr.srtgl AS sitgl , sr.srnotransaksi AS sinotransaksi , kc.knama AS sicustomer , ks.knama AS sibagianpenjualan , st.nama AS sistatus , sr.sruraian AS siuraian , sr.srmatauang AS simatauang , sr.srkurs AS sikurs , sr.srdiskonpersen AS sidiskonpersen , sr.srjmldiskon AS sijmldiskon, sr.srbiayalain AS sibiayalain , sr.srtotalpajak1detail AS sitotalpajak1detail, CASE sr.srhargatermasukpajak WHEN 0 THEN (sr.srtotalpajak1detail * 1) WHEN 1 THEN (sr.srtotalpajak1detail * 0) END AS pajak , b.bkode , srd.namabarang , srd.catatan , srd.jml , srd.satuan , srd.harga , srd.diskon , ((srd.jml * srd.harga) - srd.jmldiskon) AS total , sr.srtotaltransaksi AS sitotaltransaksi FROM m5_sr sr JOIN m1_contact kc ON sr.srcustomer = kc.kid JOIN m1_contact ks ON sr.srbagianpenjualan = ks.kid JOIN m0_status st on sr.srstatus = st.kode JOIN m5_sr_detail srd ON sr.srid = srd.idsr JOIN m1_item b on srd.idbarang = b.bid LEFT JOIN m1_expedition expe ON sr.srekspedisi = expe.ekode WHERE (sr.srstatus = 2 OR sr.srstatus = 3 OR sr.srstatus = 4 OR sr.srstatus = 7 ) ORDER BY sr.srcustomer , sr.srtgl, sr.srnotransaksi , srd.urutan;

-- RID=467 | MENU=23 | ITEM=1 | RQUERY=1 | NAME=Daftar Saldo Awal Barang (IB) | FILE=saldoawalbarang
SELECT ib.ibid, ib.ibnotransaksi , ib.ibtgl , w.wnama AS ibgudang , ib.iburaian , st.nama AS ibstatus , b.bkode , ibd.namabarang , ibd.jml, ibd.satuan , ibd.hpplama, ibd.hpp , ibd.catatan FROM m3_ib ib JOIN m1_warehouse w ON ib.ibgudang = w.wkode JOIN m0_status st ON ib.ibstatus = st.kode JOIN m3_ib_detail ibd ON ib.ibid = ibd.idib JOIN m1_item b ON ibd.idbarang = b.bid ORDER BY ib.ibtgl, ib.ibid , ib.ibnotransaksi , ibd.urutan;

