SELECT ib.ibid, ib.ibnotransaksi , ib.ibtgl , w.wnama AS ibgudang , ib.iburaian , st.nama AS ibstatus , b.bkode , ibd.namabarang , ibd.jml, ibd.satuan , ibd.hpplama, ibd.hpp , ibd.catatan FROM m3_ib ib JOIN m1_warehouse w ON ib.ibgudang = w.wkode JOIN m0_status st ON ib.ibstatus = st.kode JOIN m3_ib_detail ibd ON ib.ibid = ibd.idib JOIN m1_item b ON ibd.idbarang = b.bid ORDER BY ib.ibtgl, ib.ibid , ib.ibnotransaksi , ibd.urutan;

-- RID=568 | MENU=23 | ITEM=4 | RQUERY=1 | NAME=Saldo Awal Barang (IB) | FILE=saldoawalbarangdetail_ud
SELECT ib.ibid, ib.ibnotransaksi , ib.ibtgl , w.wnama AS ibgudang , ib.iburaian , st.nama AS ibstatus , b.bkode , ibd.namabarang , ibd.jml, ibd.satuan , ibd.hpplama, ibd.hpp , ibd.catatan FROM m3_ib ib JOIN m1_warehouse w ON ib.ibgudang = w.wkode JOIN m0_status st ON ib.ibstatus = st.kode JOIN m3_ib_detail ibd ON ib.ibid = ibd.idib JOIN m1_item b ON ibd.idbarang = b.bid ORDER BY ib.ibtgl, ib.ibid , ib.ibnotransaksi , ibd.urutan;

-- RID=1646 | MENU=23 | ITEM=5 | RQUERY=1 | NAME=Daftar Saldo Awal Barang (IB) | FILE=saldoawalbarang2
SELECT ib.ibid, ib.ibnotransaksi , ib.ibtgl , w.wnama AS ibgudang , ib.iburaian , st.nama AS ibstatus , b.bkode , ibd.namabarang , ibd.jml, ibd.satuan , ibd.hpplama, ibd.hpp , ibd.catatan FROM m3_ib ib JOIN m1_warehouse w ON ib.ibgudang = w.wkode JOIN m0_status st ON ib.ibstatus = st.kode JOIN m3_ib_detail ibd ON ib.ibid = ibd.idib JOIN m1_item b ON ibd.idbarang = b.bid;

-- RID=50001648 | MENU=23 | ITEM=6 | RQUERY=1 | NAME=Transaksi IB | FILE=SaldoAwalBarang
SELECT ibid, ibcabang, iblokasi, ibgudang, ibsumber, ibjenis, ibautonotransaksi, ibnotransaksi, ibtgl, ibkodepa, ibbagianib, ibbagianibkontak, ibmatauang, ibkurs, iburaian, ibcatatan, ibnoref, ibtglnoref, ibstatus, ibstatussebelumnya, ibjmlrevisi, ibcetakanke, ibinputuser, ibinputtgl, ibmodifikasiuser, ibmodifikasitgl, ibposting, ibpostingtgl, ibtutupperiode, ibisclose, idibdetail, idib, idbarang, namabarang, tipebarang, jml, satuan, nilaisatuan, jmlbarang, satuanbarang, matauang, kurs, hpplama, hpp, rekpersediaan, cabang, lokasi, gudang, costcenter, divisi, subdivisi, proyek, catatan, urutan, isclose FROM m3_ib ib JOIN m3_ib_detail ibd ON ib.ibid = ibd.idib ORDER BY ib.ibtgl ASC, ib.ibid ASC , ibd.idibdetail ASC;

-- RID=572 | MENU=26 | ITEM=1 | RQUERY=1 | NAME=Barang Stok Dibawah Minimum | FILE=barangbawahstokminim
SELECT i.bkode, i.bnama, i.bstokminimal, i.bstok, (i.bstok - i.bstokminimal) as variasi , IFNULL(SUM(bp.jmlbooking),0) AS bookingpo , i.bsatuan, ic.icnama, d.dnama FROM m1_item i LEFT JOIN m1_item_category ic ON i.bkategori = ic.ickode LEFT JOIN m1_division d ON i.bdivisi = d.dkode LEFT JOIN m1_item_booking_po bp ON i.bid = bp.idbarang WHERE i.bstok < i.bstokminimal GROUP BY i.bdivisi, i.bkategori, i.bkode, i.bid ORDER BY i.bdivisi, i.bkategori, i.bkode, i.bid;

-- RID=696 | MENU=34 | ITEM=1 | RQUERY=1 | NAME=Laporan Kartu Barang Serial | FILE=laporankartubarangserial
SELECT it.gudang , i.bkode , it.jenismutasi , it.tgl , it.notransaksi , it.kodepa , it.namabarang , CASE it.jenismutasi WHEN 1 THEN nst.nstjml WHEN 0 then 0 END AS jmlmasuk , CASE it.jenismutasi WHEN 1 THEN 0 WHEN 0 THEN nst.nstjml END AS jmlkeluar , it.uraian , CASE it.jenismutasi WHEN 1 THEN nst.nstkode WHEN 0 THEN nst.nstkode END AS serial FROM m1_item_transaction it JOIN m1_item i ON it.idbarang = i.bid AND i.bserial = 1 JOIN m1_no_serial_transaction nst ON it.sumber = nst.nstsumber AND it.idutama = nst.nstidtransaksi AND it.idbarang = nst.nstidbarang AND it.jenismutasi = nst.nstjenismutasi ORDER BY it.gudang ASC, i.bkode ASC, it.tgl ASC, it.jenismutasi DESC, it.sumber ASC, it.id ASC, nst.nstid ASC;

-- RID=697 | MENU=35 | ITEM=1 | RQUERY=1 | NAME=Laporan Barang Serial  | FILE=laporanbarangserial
SELECT nsi.nsiidbarang , b.bkode , nsi.nsiidserialin , it.notransaksi , it.tgl , k.knama , it.namabarang , nsi.nsijmlmasuk , nsi.nsijmlkeluar , nsi.nsisatuan , (nsi.nsijmlmasuk - nsi.nsijmlkeluar) AS jmlsisa , nsi.nsikode , nso.nsoidserialin , it2.notransaksi AS sonotransaksi , it2.tgl sotgl , kk.knama as sokanama , it2.namabarang AS sonamabarang , nso.nsojmlkeluar , nso.nsosatuan , nso.nsokode , nso.nsoidtransaksi , nso.nsoid FROM m1_no_serial_in nsi JOIN m1_item_transaction it ON it.idbarang = nsi.nsiidbarang AND it.sumber = nsi.nsisumber AND it.idutama = nsi.nsiidtransaksi AND it.jenismutasi = 1 JOIN m1_no_serial_out nso ON nsi.nsiidserialin = nso.nsoidserialin JOIN m1_item_transaction it2 ON it2.idbarang = nso.nsoidbarang AND it2.sumber = nso.nsosumber AND it2.idutama = nso.nsoidtransaksi AND it2.jenismutasi = 0 LEFT JOIN m1_item b ON it.idbarang = b.bid LEFT JOIN m1_contact k ON it.kontak = k.kid LEFT JOIN m1_item bb ON it2.idbarang = bb.bid LEFT JOIN m1_contact kk ON it2.kontak = kk.kid GROUP BY nsi.nsiidserialin , nsi.nsiidbarang , nsi.nsisumber , nsiidtransaksi, nso.nsoidbarang , nso.nsosumber , nso.nsoidtransaksi ORDER BY it.id;

-- RID=1662 | MENU=35 | ITEM=2 | RQUERY=1 | NAME=Laporan Barang Serial Pergudang | FILE=stokserialpergudang
SELECT nsi.nsiidserialin, nsi.nsigudang, w.wnama, IFNULL(c.kkode,'No Kontak') as kkode, IFNULL(c.knama,'No Kontak') as knama, nsi.nsiidbarang, i.bkode, i.bnama, nsi.nsikode, nsi.nsisumber, nsi.nsiidtransaksi, it.notransaksi, nsi.nsisatuan, nsi.nsijmlmasuk, nsi.nsijmlkeluar, nsi.nsijmlsisa, nsi.nsiisclose, (nsi.nsijmlsisa * i.bapanjang * i.balebar * i.batinggi) / 1000000000 as volume FROM m1_no_serial_in nsi JOIN m1_item i ON nsi.nsiidbarang = i.bid JOIN m1_item_transaction it ON nsi.nsisumber = it.sumber AND nsi.nsiidtransaksi = it.idutama AND nsi.nsiidbarang = it.idbarang JOIN m1_warehouse w ON nsi.nsigudang = w.wkode LEFT JOIN m1_contact c ON SUBSTR(nsi.nsikode FROM 1 FOR 5) = c.kkode WHERE nsi.nsiisclose = 0 GROUP BY nsi.nsiidserialin ORDER BY nsi.nsigudang;

-- RID=1664 | MENU=35 | ITEM=3 | RQUERY=1 | NAME=Laporan Barang Serial Pergudang (Perbarang) | FILE=stokserialpergudangperbarang
SELECT nsi.nsiidserialin, nsi.nsigudang, w.wnama, IFNULL(c.kkode,'No Kontak') as kkode, IFNULL(c.knama,'No Kontak') as knama, nsi.nsiidbarang, i.bkode, i.bnama, nsi.nsikode, nsi.nsisumber, nsi.nsiidtransaksi, it.notransaksi, nsi.nsisatuan, nsi.nsijmlmasuk, nsi.nsijmlkeluar, nsi.nsijmlsisa, nsi.nsiisclose, (nsi.nsijmlsisa * i.bapanjang * i.balebar * i.batinggi) / 1000000000 as volume FROM m1_no_serial_in nsi JOIN m1_item i ON nsi.nsiidbarang = i.bid JOIN m1_item_transaction it ON nsi.nsisumber = it.sumber AND nsi.nsiidtransaksi = it.idutama AND nsi.nsiidbarang = it.idbarang JOIN m1_warehouse w ON nsi.nsigudang = w.wkode LEFT JOIN m1_contact c ON SUBSTR(nsi.nsikode FROM 1 FOR 5) = c.kkode WHERE nsi.nsiisclose = 0 GROUP BY nsi.nsiidserialin ORDER BY nsi.nsigudang, nsi.nsiidbarang;

