SELECT * FROM m2r_kartu_stok ORDER BY kskodebarang ASC;

-- RID=454592 | MENU=36 | ITEM=7 | RQUERY=2 | NAME=Kartu Stok Rekap Per Kategori (Detail) | FILE=kartustokrekap_detail
SELECT idlogin, ksnourut, ksid, ksgudang, ksgudangnama, kskategoribarang, kskategoribarangnama, ksidbarang, kskodebarang, kstipebarang, ksnamabarang, kssatuanbarang, kstgl, kssumber, ksnotransaksi, kskontak, kskontakkode, kskontaknama, ksuraian, kscatatan, kscatatandetail, ksmatauang, kskurs, ksharga, ksdiskon, ksjmldiskon, ksjenismutasi, ksjmlmasuk, kshargamasuk, ksnilaimasuk, ksjmlkeluar, kshargakeluar, ksnilaikeluar, kssaldojml, CASE WHEN cast(kssaldojml as decimal(18,2)) = 0 THEN 0 ELSE kssaldohpp END as kssaldohpp, kssaldonilai, kspostingtgl, ksinputtgl, idmsmq, ksuserid, kscustomtext1, kscustomtext2, kscustomtext3, kscustomtext4, kscustomtext5, kscustomint1, kscustomint2, kscustomint3, kscustomint4, kscustomint5, kscustomdbl1, CASE WHEN cast(kscustomdbl1 as decimal(18,2)) = 0 THEN 0 ELSE kscustomdbl2 END as kscustomdbl2, kscustomdbl3, kscustomdbl4, kscustomdbl5, kscustomdate1, kscustomdate2, kscustomdate3, kscustomdate4, kscustomdate5, i.brekpersediaan, i.brekhargapokok, i.brekpenjualan , i.brekreturpenjualan , i.brekreturpembelian , i.brekdiskonpembelian , i.brekdiskonpenjualan , i.brekkonsinyasi FROM m2r_kartu_stok ks join m1_item i on ks.ksidbarang = i.bid WHERE i.bjenis <> "J" ORDER BY kskategoribarang ASC, kskodebarang ASC;

-- RID=454593 | MENU=36 | ITEM=8 | RQUERY=2 | NAME=Kartu Stok Rekap Per Kategori (Global) | FILE=kartustokrekap_global
SELECT idlogin, ksnourut, ksid, ksgudang, ksgudangnama, kskategoribarang, kskategoribarangnama, ksidbarang, kskodebarang, kstipebarang, ksnamabarang, kssatuanbarang, kstgl, kssumber, ksnotransaksi, kskontak, kskontakkode, kskontaknama, ksuraian, kscatatan, kscatatandetail, ksmatauang, kskurs, ksharga, ksdiskon, ksjmldiskon, ksjenismutasi, SUM(ksjmlmasuk) as ksjmlmasuk, SUM(ksnilaimasuk) / SUM(ksjmlmasuk) as kshargamasuk, SUM(ksnilaimasuk) as ksnilaimasuk, SUM(ksjmlkeluar) as ksjmlkeluar, SUM(ksnilaikeluar) / SUM(ksjmlkeluar) as kshargakeluar, SUM(ksnilaikeluar) as ksnilaikeluar, SUM(kssaldojml) as kssaldojml, SUM(kssaldonilai) / SUM(kssaldojml) as kssaldohpp, SUM(kssaldonilai) as kssaldonilai, kspostingtgl, ksinputtgl, idmsmq, ksuserid, kscustomtext1, kscustomtext2, kscustomtext3, kscustomtext4, kscustomtext5, kscustomint1, kscustomint2, kscustomint3, kscustomint4, kscustomint5, SUM(kscustomdbl1) as kscustomdbl1, SUM(kscustomdbl3) / SUM(kscustomdbl1) as kscustomdbl2, SUM(kscustomdbl3) as kscustomdbl3, kscustomdbl4, kscustomdbl5, kscustomdate1, kscustomdate2, kscustomdate3, kscustomdate4, kscustomdate5 FROM m2r_kartu_stok GROUP BY kskategoribarang ASC ORDER BY kskategoribarang ASC, kskodebarang ASC;

-- RID=50000535 | MENU=36 | ITEM=9 | RQUERY=2 | NAME=Inventory Actual Balance Sheet | FILE=inventoryactualbalancesheet
SELECT * FROM m2r_kartu_stok ORDER BY kskategoribarang ASC, kskodebarang ASC;

-- RID=50000562 | MENU=36 | ITEM=10 | RQUERY=2 | NAME=Laporan Stok | FILE=stok
SELECT idlogin , idmsmq , kodebarang , namabarang , idbarang , satuan , IF(g1 = "","-",g1) as g1 , j1, IF(g2 = "","-",g2) as g2 , j2, IF(g3 = "","-",g3) as g3 , j3, IF(g4 = "","-",g4) as g4 , j4, IF(g5 = "","-",g5) as g5 , j5, IF(g6 = "","-",g6) as g6 , j6, IF(g7 = "","-",g7) as g7 , j7, IF(g8 = "","-",g8) as g8 , j8, IF(g9 = "","-",g9) as g9 , j9, IF(g10 = "","-",g10) as g10 , j10 , total , supplier FROM m2r_stok ORDER BY kodebarang ASC;

-- RID=50000612 | MENU=36 | ITEM=11 | RQUERY=2 | NAME=Kartu Stok (Average) | FILE=kartustokaverage_1baris
SELECT * FROM m2r_kartu_stok ORDER BY kskodebarang ASC, ksnourut ASC;

-- RID=454 | MENU=37 | ITEM=1 | RQUERY=2 | NAME=Mutasi Stok | FILE=mutasistok
SELECT ms.*, GROUP_CONCAT(DISTINCT nbt.nbtkode) as nobatch FROM m2r_mutasi_stok_detail ms LEFT JOIN m1_item_transaction it ON ms.msid = it.id LEFT JOIN m1_no_batch_transaction nbt ON it.sumber = nbt.nbtsumber AND it.jenismutasi = nbt.nbtjenismutasi AND it.idutama = nbt.nbtidtransaksi AND it.idbarang = nbt.nbtidbarang GROUP BY msgudang ASC, mskodebarang ASC, msnourut ASC ORDER BY msgudang ASC, mskodebarang ASC, msnourut ASC;

-- RID=853 | MENU=37 | ITEM=2 | RQUERY=2 | NAME=Mutasi Stok Cost Center | FILE=mutasistokCostCenter
SELECT * FROM m2r_mutasi_stok_detail ORDER BY msgudang ASC, mskodebarang ASC, msnourut ASC;

-- RID=854 | MENU=37 | ITEM=3 | RQUERY=2 | NAME=Mutasi Stok Divisi | FILE=mutasistokDivisi
SELECT * FROM m2r_mutasi_stok_detail ORDER BY msgudang ASC, mskodebarang ASC, msnourut ASC;

-- RID=855 | MENU=37 | ITEM=4 | RQUERY=2 | NAME=Mutasi Stok Proyek | FILE=mutasistokProyek
SELECT * FROM m2r_mutasi_stok_detail ORDER BY msgudang ASC, mskodebarang ASC, msnourut ASC;

-- RID=1595 | MENU=37 | ITEM=5 | RQUERY=2 | NAME=Mutasi Stok Rekap | FILE=mutasistokrekap
SELECT msgudangnama , mskodebarang, msnamabarang , mssatuanbarang , saldoawal AS saldoawal, masuk AS masuk, keluar AS keluar, saldoakhir AS saldoakhir , case i.baktif when 1 then 'AKTIF' else 'NOF AKTIF' end as bstatus, tr.notransaksi as last_notransaksi, tr.tgl as last_tgltransaksi FROM m2r_mutasi_stok_rekap ms JOIN m1_item i ON ms.mskodebarang = i.bkode AND i.bjenis = 'P' LEFT JOIN (SELECT it.idbarang, SUBSTRING_INDEX(GROUP_CONCAT(it.tgl ORDER BY it.tgl DESC, it.inputtgl DESC, it.customint10 DESC, it.jenismutasi DESC, it.idutama DESC, it.iddetail DESC) ,',',1) as tgl, SUBSTRING_INDEX(GROUP_CONCAT(it.notransaksi ORDER BY it.tgl DESC, it.inputtgl DESC, it.customint10 DESC, it.jenismutasi DESC, it.idutama DESC, it.iddetail DESC) ,',',1) as notransaksi, SUBSTRING_INDEX(GROUP_CONCAT(it.gudang ORDER BY it.tgl DESC, it.inputtgl DESC, it.customint10 DESC, it.jenismutasi DESC, it.idutama DESC, it.iddetail DESC) ,',',1) as gudang FROM m1_item_transaction it GROUP BY it.idbarang, it.gudang ) as tr ON ms.msgudang = tr.gudang AND i.bid = tr.idbarang ORDER BY msgudang ASC, mskodebarang ASC, msnourut ASC;

-- RID=50000530 | MENU=37 | ITEM=6 | RQUERY=2 | NAME=Mutasi Stok Rekap Per Shift | FILE=mutasistokrekap_Pershift
SELECT msgudangnama , mskodebarang, msnamabarang , mssatuanbarang , mscustomdbl1 AS saldoawal, mscustomdbl2 AS masuk, mscustomdbl3 AS keluar, mscustomdbl4 AS saldoakhir , mscustomtext2 , CASE mscustomtext2 WHEN 1 THEN "Shift Pagi" WHEN 2 THEN "Shift Siang" END AS "Shift" FROM m2r_mutasi_stok_detail ORDER BY msgudang ASC, mskodebarang ASC, msnourut ASC;

-- RID=50000533 | MENU=37 | ITEM=7 | RQUERY=2 | NAME=Mutasi Stok | FILE=mutasistok
SELECT * FROM m2r_mutasi_stok_detail ORDER BY msgudang ASC, mskodebarang ASC, msnourut ASC;

-- RID=50000534 | MENU=37 | ITEM=8 | RQUERY=2 | NAME=Laporan Inventory Historis Per Grup | FILE=inventoryhistorispergrup
SELECT msgudangnama , mskodebarang, msnamabarang , mssatuanbarang , SUM(mscustomdbl1) AS saldoawal, SUM(mscustomdbl2 )AS masuk, SUM(mscustomdbl3) AS keluar, SUM(mscustomdbl4) AS saldoakhir, i.bkategori AS mskategori, ic.icnama AS mskategorinama FROM m2r_mutasi_stok_detail ms JOIN m1_item i ON i.bid = ms.msidbarang JOIN m1_item_category ic ON ic.ickode = i.bkategori GROUP BY msgudang , msidbarang ORDER BY mskategori ASC, msgudang ASC, mskodebarang ASC, msnourut ASC;

-- RID=50000576 | MENU=37 | ITEM=9 | RQUERY=2 | NAME=Mutasi Stok Rekap Per Sumber | FILE=mutasistokrekapsumber
SELECT * , (mssaldoawal * mshargajual) AS nilaisaldoawal , (mssaldoakhir * mshargajual) AS nilaisaldoakhir FROM m2r_mutasi_stok_sumber ORDER BY msgudang ASC, mskodebarang ASC;

-- RID=50001778 | MENU=37 | ITEM=10 | RQUERY=1 | NAME=Laporan Stok | FILE=lapstok
SELECT b.bkode, b.bnama, b.bjmlorderjual, b.bstok , b.bjmlorderjual + b.bstok as tstok FROM m1_item b ORDER BY b.bkode ASC;

-- RID=747 | MENU=38 | ITEM=1 | RQUERY=1 | NAME=Laporan Kartu Barang Batch | FILE=laporankartubarangbatch
SELECT it.gudang , i.bkode , it.jenismutasi , it.tgl , it.notransaksi , it.kodepa , it.namabarang , CASE it.jenismutasi WHEN 1 THEN nbi.nbijmlmasuk WHEN 0 then 0 END AS jmlmasuk , CASE it.jenismutasi WHEN 1 THEN 0 WHEN 0 THEN nbo.nbojmlkeluar END AS jmlkeluar , it.uraian , CASE it.jenismutasi WHEN 1 THEN nbi.nbikode WHEN 0 THEN nbo.nbokode END AS batch FROM m1_item_transaction it JOIN m1_item i ON it.idbarang = i.bid AND i.bbatch = 1 LEFT JOIN m1_no_batch_in nbi ON it.idbarang = nbi.nbiidbarang AND it.sumber = nbi.nbisumber AND it.idutama = nbi.nbiidtransaksi AND it.jenismutasi = 1 LEFT JOIN m1_no_batch_out nbo ON it.idbarang = nbo.nboidbarang AND it.sumber = nbo.nbosumber AND it.idutama = nbo.nboidtransaksi AND it.jenismutasi = 0 ORDER BY it.id;

-- RID=500056 | MENU=38 | ITEM=2 | RQUERY=1 | NAME=Berita Acara Stok Opname Gudang Barang Jadi  | FILE=beritaacara_stokopname_sin
SELECT w.wkode , w.wnama , k.idbarang , b.bkode , b.bnama , nbi.nbikode , nbi.nbicustomdate1, k.stok , nbi.nbijmlsisa FROM m1_item_stock_warehouse k JOIN m1_item b ON k.idbarang = b.bid JOIN m1_warehouse w ON k.kgudang = w.wkode LEFT JOIN m1_no_batch_in nbi ON k.idbarang = nbi.nbiidbarang AND k.kgudang = nbi.nbigudang AND nbi.nbiisclose = 0 ORDER BY k.kgudang ASC , b.bkode , b.bnama;

-- RID=5000523 | MENU=38 | ITEM=3 | RQUERY=2 | NAME=Rekap Stok Barang Batch | FILE=rekapbatchpertanggal
SELECT * FROM m2r_batch_pertanggal ORDER BY bpgudang, bpkodebarang, bpnobatch;

-- RID=5000527 | MENU=38 | ITEM=4 | RQUERY=2 | NAME=Mutasi Stok Barang Batch | FILE=mutasibatch
SELECT * FROM m2r_batch_pertanggal ORDER BY bpgudang, bpkodebarang, bpnobatch;

-- RID=792 | MENU=39 | ITEM=1 | RQUERY=1 | NAME=Laporan Barang Batch | FILE=laporanbarangbatch
SELECT nbi.nbiidbarang , b.bkode , nbi.nbiidbatchin , it.notransaksi , it.tgl , k.knama , it.namabarang , nbi.nbijmlmasuk , nbi.nbijmlkeluar , nbi.nbisatuan , (nbi.nbijmlmasuk - nbi.nbijmlkeluar) AS jmlsisa , nbi.nbikode, nbo.nboidbatchin, it2.notransaksi AS sonotransaksi , it2.tgl sotgl , kk.knama as sokanama , it2.namabarang AS sonamabarang , nbo.nbojmlkeluar , nbo.nbosatuan , nbo.nbokode , nbo.nboidtransaksi , nbo.nboid FROM m1_no_batch_in nbi JOIN m1_item_transaction it ON it.idbarang = nbi.nbiidbarang AND it.sumber = nbi.nbisumber AND it.idutama = nbi.nbiidtransaksi JOIN m1_no_batch_out nbo JOIN m1_item_transaction it2 ON it2.idbarang = nbo.nboidbarang AND it2.sumber = nbo.nbosumber AND it2.idutama = nbo.nboidtransaksi LEFT JOIN m1_item b ON it.idbarang = b.bid LEFT JOIN m1_contact k ON it.kontak = k.kid LEFT JOIN m1_item bb ON it2.idbarang = bb.bid LEFT JOIN m1_contact kk ON it2.kontak = kk.kid GROUP BY nbi.nbiidbatchin , nbi.nbiidbarang , nbi.nbisumber , nbiidtransaksi , nbo.nboidbarang , nbo.nbosumber , nbo.nboidtransaksi ORDER BY it.id;

-- RID=793 | MENU=39 | ITEM=2 | RQUERY=1 | NAME=Laporan Barang Batch Pergudang (Perkontak) | FILE=stokbatchperkontakpergudang
SELECT nbi.nbiidbatchin, nbi.nbigudang, w.wnama, IFNULL(c.kkode,'No Kontak') as kkode, IFNULL(c.knama,'No Kontak') as knama, nbi.nbiidbarang, i.bkode, i.bnama, nbi.nbikode, nbi.nbisumber, nbi.nbiidtransaksi, it.notransaksi, nbi.nbisatuan, nbi.nbijmlmasuk, nbi.nbijmlkeluar, nbi.nbijmlsisa, nbi.nbiisclose, (nbi.nbijmlsisa * i.bapanjang * i.balebar * i.batinggi) / 1000000000 as volume FROM m1_no_batch_in nbi JOIN m1_item i ON nbi.nbiidbarang = i.bid JOIN m1_item_transaction it ON nbi.nbisumber = it.sumber AND nbi.nbiidtransaksi = it.idutama AND nbi.nbiidbarang = it.idbarang JOIN m1_warehouse w ON nbi.nbigudang = w.wkode LEFT JOIN m1_contact c ON SUBSTR(nbi.nbikode FROM 1 FOR 5) = c.kkode WHERE nbi.nbiisclose = 0 GROUP BY nbi.nbiidbatchin ORDER BY nbi.nbigudang, it.kontak;

-- RID=794 | MENU=39 | ITEM=3 | RQUERY=1 | NAME=Laporan Barang Batch Pergudang (Perbarang) | FILE=stokbatchpergudangperbarang
SELECT nbi.nbiidbatchin, nbi.nbigudang, w.wnama, IFNULL(c.kkode,'No Kontak') as kkode, IFNULL(c.knama,'No Kontak') as knama, nbi.nbiidbarang, i.bkode, i.bnama, nbi.nbikode, nbi.nbisumber, nbi.nbiidtransaksi, it.notransaksi, nbi.nbisatuan, nbi.nbijmlmasuk, nbi.nbijmlkeluar, nbi.nbijmlsisa, nbi.nbiisclose, (nbi.nbijmlsisa * i.bapanjang * i.balebar * i.batinggi) / 1000000000 as volume FROM m1_no_batch_in nbi JOIN m1_item i ON nbi.nbiidbarang = i.bid JOIN m1_item_transaction it ON nbi.nbisumber = it.sumber AND nbi.nbiidtransaksi = it.idutama AND nbi.nbiidbarang = it.idbarang JOIN m1_warehouse w ON nbi.nbigudang = w.wkode LEFT JOIN m1_contact c ON SUBSTR(nbi.nbikode FROM 1 FOR 5) = c.kkode WHERE nbi.nbiisclose = 0 GROUP BY nbi.nbiidbatchin ORDER BY nbi.nbigudang, nbi.nbiidbarang;

-- RID=795 | MENU=39 | ITEM=4 | RQUERY=1 | NAME=Laporan Barang Batch Pergudang | FILE=stokbatchpergudang
SELECT nbi.nbiidbatchin, nbi.nbigudang, w.wnama, IFNULL(c.kkode,'No Kontak') as kkode, IFNULL(c.knama,'No Kontak') as knama, nbi.nbiidbarang, i.bkode, i.bnama, nbi.nbikode, nbi.nbisumber, nbi.nbiidtransaksi, it.notransaksi, nbi.nbisatuan, nbi.nbijmlmasuk, nbi.nbijmlkeluar, nbi.nbijmlsisa, nbi.nbiisclose, (nbi.nbijmlsisa * i.bapanjang * i.balebar * i.batinggi) / 1000000000 as volume FROM m1_no_batch_in nbi JOIN m1_item i ON nbi.nbiidbarang = i.bid JOIN m1_item_transaction it ON nbi.nbisumber = it.sumber AND nbi.nbiidtransaksi = it.idutama AND nbi.nbiidbarang = it.idbarang JOIN m1_warehouse w ON nbi.nbigudang = w.wkode LEFT JOIN m1_contact c ON SUBSTR(nbi.nbikode FROM 1 FOR 5) = c.kkode WHERE nbi.nbiisclose = 0 GROUP BY nbi.nbiidbatchin ORDER BY nbi.nbigudang;

-- RID=822 | MENU=40 | ITEM=1 | RQUERY=1 | NAME=Daftar Pengisian Bahan Bakar (RF) | FILE=listpengisianbahanbakar
SELECT rf.rfdimintaoleh, k.knama AS dimintaoleh, ih.bkode AS kodebarang, rf.rfnotransaksi, rf.rftgl, rfd.catatan, rf.rfcustomtext1 AS jampengisian, rf.rfuraian, rfd.namabarang, rfd.satuan, rfd.jml, rfd.stokterakhir AS hourmeter, st.nama AS statusrf FROM m3_rf rf JOIN m3_rf_detail rfd ON rf.rfid = rfd.idrf JOIN m1_item_hauling ih ON rfd.idbarang = ih.bid JOIN m1_contact k ON rf.rfdimintaoleh = k.kid JOIN m0_status st ON rf.rfstatus = st.kode ORDER BY rf.rfnotransaksi, ih.bkode, rf.rftgl, k.knama;

-- RID=826 | MENU=40 | ITEM=2 | RQUERY=1 | NAME=Laporan Pengisian Bahan Bakar (RF)  | FILE=PemakaianSolar3
SELECT rf.rfdimintaoleh, k.knama AS dimintaoleh, ih.bkode AS kodebarang, rf.rfnotransaksi, rf.rftgl, rfd.catatan, rf.rfcustomtext1 AS jampengisian, rf.rfuraian, rfd.namabarang, rfd.satuan, rfd.jml, rfd.stokterakhir AS hourmeter, st.nama AS statusrf FROM m3_rf rf JOIN m3_rf_detail rfd ON rf.rfid = rfd.idrf JOIN m1_item_hauling ih ON rfd.idbarang = ih.bid JOIN m1_contact k ON rf.rfdimintaoleh = k.kid JOIN m0_status st ON rf.rfstatus = st.kode ORDER BY rf.rfnotransaksi, ih.bkode, rf.rftgl, k.knama;

-- RID=806 | MENU=40 | ITEM=3 | RQUERY=1 | NAME=Laporan Pengisian Bahan Bakar (RF) | FILE=PemakaianSolar
SELECT rf.rfdimintaoleh, k.knama AS dimintaoleh, ih.bkode AS kodebarang, rf.rfnotransaksi, rf.rftgl, rfd.catatan, rf.rfcustomtext1 AS jampengisian, rf.rfuraian, rfd.namabarang, rfd.satuan, rfd.jml, rfd.stokterakhir AS hourmeter, st.nama AS statusrf FROM m3_rf rf JOIN m3_rf_detail rfd ON rf.rfid = rfd.idrf JOIN m1_item_hauling ih ON rfd.idbarang = ih.bid JOIN m1_contact k ON rf.rfdimintaoleh = k.kid JOIN m0_status st ON rf.rfstatus = st.kode ORDER BY rf.rfnotransaksi, ih.bkode, rf.rftgl, k.knama;

-- RID=823 | MENU=40 | ITEM=4 | RQUERY=1 | NAME=Pengisian Bahan Bakar (RF) | FILE=pengisianbahanbakardetail
SELECT rf.rfdimintaoleh, k.knama AS dimintaoleh, ih.bkode AS kodebarang, rf.rfnotransaksi, rf.rftgl, rfd.catatan, rf.rfcustomtext1 AS jampengisian, rf.rfuraian, rfd.namabarang, rfd.satuan, rfd.jml, rfd.stokterakhir AS hourmeter, st.nama AS statusrf FROM m3_rf rf JOIN m3_rf_detail rfd ON rf.rfid = rfd.idrf JOIN m1_item_hauling ih ON rfd.idbarang = ih.bid JOIN m1_contact k ON rf.rfdimintaoleh = k.kid JOIN m0_status st ON rf.rfstatus = st.kode ORDER BY rf.rfnotransaksi, ih.bkode, rf.rftgl, k.knama;

-- RID=824 | MENU=40 | ITEM=5 | RQUERY=1 | NAME=Pengisian Bahan Bakar (RF) | FILE=pengisianbahanbakardetail2
SELECT rf.rfdimintaoleh, k.knama AS dimintaoleh, ih.bkode AS kodebarang, rf.rfnotransaksi, rf.rftgl, rfd.catatan, rf.rfcustomtext1 AS jampengisian, rf.rfuraian, rfd.namabarang, rfd.satuan, rfd.jml, rfd.stokterakhir AS hourmeter, st.nama AS statusrf FROM m3_rf rf JOIN m3_rf_detail rfd ON rf.rfid = rfd.idrf JOIN m1_item_hauling ih ON rfd.idbarang = ih.bid JOIN m1_contact k ON rf.rfdimintaoleh = k.kid JOIN m0_status st ON rf.rfstatus = st.kode ORDER BY rf.rfnotransaksi, ih.bkode, rf.rftgl, k.knama;

-- RID=830 | MENU=41 | ITEM=1 | RQUERY=1 | NAME=Daftar Time Sheet / Daily Check (DC) | FILE=ListTimeSheet
SELECT dc.dcid , kk.knama AS dcmintake , dc.dcnotransaksi, dc.dctgl, CASE dc.dcshift WHEN 1 THEN "Night" WHEN 0 THEN "DAY" END AS dcshift , (CASE dc.dcstatus WHEN 0 THEN 'Draft' WHEN 1 THEN 'Minta Approve' WHEN 2 THEN 'Approved' WHEN 3 THEN 'Inprogress' WHEN 4 THEN 'Complete' WHEN 5 THEN 'Revisi' WHEN 6 THEN 'Reject' WHEN 7 THEN 'Close' WHEN 8 THEN 'Approve1' WHEN 9 THEN 'Approve2' WHEN 10 THEN 'Approve3' WHEN 11 THEN 'Approve4' WHEN 12 THEN 'Hapus' END) AS dcstatus, k.knama AS dcdimintaoleh , b.bkode , dc.dcnamabarang , dc.dchmstart , dc.dchmstop , (dc.dchmstop - dc.dchmstart) as total , dcd.opstart, dcd.opend , dcd.sbstart, dcd.sbend, dcd.spstart, dcd.spend, dcd.rfstart , dcd.rfend, dcd.bdstart, dcd.bdend, dcd.catatan FROM m3_dc dc JOIN m1_contact kk ON dc.dcmintake = kk.kid JOIN m1_item b ON dc.dcidbarang = b.bid JOIN m3_dc_detail dcd ON dc.dcid = dcd.iddc LEFT JOIN m1_contact k ON dc.dcdimintaoleh = k.kid LEFT JOIN m1_location l ON dc.dclokasi = l.lkode ORDER BY dc.dcid, dc.dcnotransaksi, dcd.urutan;

-- RID=825 | MENU=41 | ITEM=2 | RQUERY=1 | NAME=Time Sheet / Daily Check (DC) | FILE=TimeSheet
SELECT dc.dcid , kk.knama AS dcmintake , dc.dcnotransaksi, dc.dctgl, CASE dc.dcshift WHEN 1 THEN "Night" WHEN 0 THEN "DAY" END AS dcshift , (CASE dc.dcstatus WHEN 0 THEN 'Draft' WHEN 1 THEN 'Minta Approve' WHEN 2 THEN 'Approved' WHEN 3 THEN 'Inprogress' WHEN 4 THEN 'Complete' WHEN 5 THEN 'Revisi' WHEN 6 THEN 'Reject' WHEN 7 THEN 'Close' WHEN 8 THEN 'Approve1' WHEN 9 THEN 'Approve2' WHEN 10 THEN 'Approve3' WHEN 11 THEN 'Approve4' WHEN 12 THEN 'Hapus' END) AS dcstatus, k.knama AS dcdimintaoleh , b.bkode , dc.dcnamabarang , dc.dchmstart , dc.dchmstop , (dc.dchmstop - dc.dchmstart) as total , dcd.opstart, dcd.opend , dcd.sbstart, dcd.sbend, dcd.spstart, dcd.spend, dcd.rfstart , dcd.rfend, dcd.bdstart, dcd.bdend, dcd.catatan FROM m3_dc dc LEFT JOIN m1_location l ON dc.dclokasi = l.lkode JOIN m1_contact kk ON dc.dcmintake = kk.kid JOIN m1_item b ON dc.dcidbarang = b.bid JOIN m3_dc_detail dcd ON dc.dcid = dcd.iddc LEFT JOIN m1_contact k ON dc.dcdimintaoleh = k.kid ORDER BY dc.dcid, dc.dcnotransaksi, dcd.urutan;

-- RID=1093 | MENU=47 | ITEM=1 | RQUERY=1 | NAME=Laporan Analisa Stok | FILE=LaporanAnalisaStok
SELECT b.bkode , b.bnama , b.bstok AS stok, IFNULL(SUM(bp.jmlbooking),0) AS bookingvendor , IFNULL(SUM(book.jmlbooking),0) AS bookingcustomer, b.bstokminimal, b.bstokmaksimal, IFNULL(SUM(bp.jmlbooking),0) + b.bstok as total, b.bkategori, b.bcustom1 as min1, b.bcustom2 as max1, b.bcustom3 as min2, b.bcustom4 as max2 FROM m1_item b LEFT JOIN m1_item_booking_po bp ON b.bid = bp.idbarang LEFT JOIN m1_item_booking book ON b.bid = book.idbarang WHERE b.baktif = 1 GROUP BY b.bkode, b.bid ORDER BY b.bkode, b.bid;

-- RID=1005 | MENU=47 | ITEM=2 | RQUERY=1 | NAME=Laporan Stok Per Lokasi | FILE=laporanpersediaanbarangpergudang
SELECT isw.idbarang, isw.kgudang , SUM(isw.stok) AS stok , w.wnama , b.bkode , b.btipe , b.bnama , b.bsatuan , blg.blgkodelokasi , blg.blgidlokasi FROM m1_item_stock_warehouse isw JOIN m1_warehouse w ON isw.kgudang = w.wkode JOIN m1_item b ON isw.idbarang = b.bid LEFT JOIN m1_item_location_warehouse blg ON (isw.kgudang = blg.blggudang AND isw.idbarang = blg.blgidbarang) LEFT JOIN m1_item_location il ON blg.blgidlokasi = il.ilid GROUP BY isw.kgudang , isw.idbarang, blg.blgkodelokasi ORDER BY isw.kgudang , blg.blgkodelokasi , w.wkode , w.wnama , isw.idbarang;

-- RID=1605 | MENU=47 | ITEM=3 | RQUERY=1 | NAME=Laporan Stok Per Barang | FILE=stokperbarangpergudang
SELECT isw.idbarang, isw.kgudang , isw.stok AS stok , w.wnama , b.bkode , b.btipe , b.bnama , b.bsatuan, b.bstokminimal, b.bstokmaksimal FROM m1_item_stock_warehouse isw JOIN m1_warehouse w ON isw.kgudang = w.wkode JOIN m1_item b ON isw.idbarang = b.bid ORDER BY isw.idbarang , isw.kgudang , w.wkode , w.wnama;

-- RID=1153 | MENU=47 | ITEM=4 | RQUERY=1 | NAME=Laporan Stok Per Gudang | FILE=stokpergudang
SELECT b.bid as idbarang, w.wkode as kgudang , w.wnama , b.bkode , b.btipe , b.bnama , b.bsatuan , IFNULL(SUM(isw.stok),0) AS stok , b.bjmlorderbeli, b.bhppaverage, b.bdivisi FROM m1_item b JOIN m1_warehouse w ON b.bjenis = 'P' JOIN m1_item_stock_warehouse isw ON isw.kgudang = w.wkode AND isw.idbarang = b.bid AND isw.stok <> 0 GROUP BY isw.kgudang , w.wkode , w.wnama , b.bdivisi, b.bkode, isw.idbarang ORDER BY isw.kgudang , w.wkode , w.wnama , b.bdivisi, b.bkode, isw.idbarang;

-- RID=50003839 | MENU=47 | ITEM=5 | RQUERY=1 | NAME=Laporan Stok Per Gudang | FILE=stokpergudang
SELECT b.bid as idbarang, w.wkode as kgudang , w.wnama , b.bkode , b.btipe , b.bnama , b.bsatuan , IFNULL(SUM(isw.stok),0) AS stok , b.bjmlorderbeli, b.bhppaverage, b.bdivisi FROM m1_item b JOIN m1_warehouse w ON b.bjenis = 'P' JOIN m1_item_stock_warehouse isw ON isw.kgudang = w.wkode AND isw.idbarang = b.bid GROUP BY isw.kgudang , w.wkode , w.wnama , b.bdivisi, b.bkode, isw.idbarang ORDER BY isw.kgudang , w.wkode , w.wnama , b.bdivisi, b.bkode, isw.idbarang;

-- RID=1152 | MENU=48 | ITEM=3 | RQUERY=1 | NAME=Laporan Barang Retur | FILE=laporanpersediaanbarangpergudang_retur
SELECT k.knama , isw.idbarang, isw.kgudang , blg.blgkodelokasi , blg.blgidlokasi , SUM(isw.stok) AS stok , w.wnama , b.bkode , b.btipe , b.bnama , b.bsatuan FROM m1_item_stock_warehouse isw JOIN m1_warehouse w ON isw.kgudang = w.wkode JOIN m1_item b ON isw.idbarang = b.bid JOIN m1_item_supplier iss ON isw.idbarang = iss.isidbarang JOIN m1_contact k ON iss.isidkontak = k.kid LEFT JOIN m1_item_location_warehouse blg ON (isw.kgudang = blg.blggudang AND isw.idbarang = blg.blgidbarang) LEFT JOIN m1_item_location il ON blg.blgidlokasi = il.ilid GROUP BY iss.isidkontak , isw.kgudang , blg.blgkodelokasi , isw.idbarang ORDER BY iss.isidkontak , isw.kgudang , blg.blgkodelokasi , w.wkode , w.wnama , isw.idbarang;

-- RID=50000556 | MENU=49 | ITEM=1 | RQUERY=1 | NAME=Saldo Jumlah Saldo HPP | FILE=saldoJMLsaldoHPP
SELECT it.namabarang, it.tgl, it.saldohpp, it.saldojml FROM m1_item_transaction it JOIN m1_item b ON it.idbarang = b.bid WHERE (it.saldojml < 0 OR it.saldohpp < 0) ORDER BY it.idbarang, it.tgl, it.inputtgl, it.customint10, it.jenismutasi, it.idutama, it.iddetail;

-- RID=50000586 | MENU=50 | ITEM=1 | RQUERY=2 | NAME=Rekap Barang Konsinyasi | FILE=rekapbarangkonsinyasi
SELECT rbk.* , b.bkode FROM m2r_rekap_barang_konsinyasi rbk JOIN m1_item b ON rbk.rbkidbarang = b.bid ORDER BY rbkgudang, rbktgl, rbksumber, rbkidutama, rbknotransaksi, rbkiddetail, rbkidbarang;

-- RID=50003786 | MENU=55 | ITEM=1 | RQUERY=2 | NAME=Daily Available Stock | FILE=DailyAvailableStock
select * FROM m2r_dailyavailablestock ORDER BY urut;

-- RID=50003806 | MENU=55 | ITEM=2 | RQUERY=2 | NAME=Raw Material Stock | FILE=groupingrm
SELECT grm.* FROM m2r_groupingrm grm left join m1_department dp on dpkode = grm.departemen ORDER BY divisi, case divisi when "BR" then dp.dpcustomint1 when "BW" then dp.dpcustomint2 END ASC , departemen;

-- RID=50003827 | MENU=55 | ITEM=3 | RQUERY=2 | NAME=Daily Rekon Bahan Maklon | FILE=DailyRekonBahanMaklon
select * FROM m2r_dailyavailablestock ORDER BY urut;

-- RID=50003831 | MENU=55 | ITEM=4 | RQUERY=2 | NAME=Hedging Daily Available Stock | FILE=HedgingDailyAvailableStock
select * FROM m2r_dailyavailablestockhedging ORDER BY urut;

-- RID=50003787 | MENU=56 | ITEM=1 | RQUERY=1 | NAME=Stock Minus | FILE=stokminus
SELECT i.bkode, i.bnama, it.tgl, it.sumber, it.notransaksi, it.saldojml as stok, i.bsatuan FROM m1_item_transaction it JOIN m1_item i ON it.idbarang = i.bid AND i.bjenis <> 'J' AND i.bjenis <> 'V' AND i.bhpp = 'R' JOIN m0_nomor n ON it.sumber = n.kodetabel AND n.transaksihpp = 1 WHERE ROUND(it.saldojml,2) < 0 ORDER BY i.bkode, it.tgl, it.inputtgl, it.customint10, it.jenismutasi, it.idutama, it.iddetail;

